    const reversedRoot = merkleFold([...addresses].reverse())
    const rotatedRoot = merkleFold([...addresses.slice(3), ...addresses.slice(0, 3)])
    const anyWaveSameRoot = root === reversedRoot && root === rotatedRoot && isUuid(root)
